    fileName: "BlockChartRadialBar.client.vue",
    file: '<template>\n  <div class="h-[550px] w-full">\n    <apexchart width="100%" height="100%" type="radialBar" :options="options" :series="series" />\n  </div>\n</template>\n\n<script lang="ts" setup>\n  import type { ApexOptions } from "apexcharts";\n\n  const series: ApexOptions["series"] = [70, 30, 60];\n\n  const options: ApexOptions = {\n    plotOptions: {\n      radialBar: {\n        track: {\n          background: "rgba(var(--gray100),1)",\n        },\n        dataLabels: {\n          name: {\n            fontFamily: "inherit",\n            fontWeight: 600,\n            fontSize: "24px",\n          },\n          total: {\n            show: true,\n            label: "Total",\n            fontFamily: "inherit",\n            fontWeight: 600,\n            fontSize: "24px",\n            formatter(opts) {\n              const total = opts.config?.series?.reduce((acc: number, cur: number) => acc + cur, 0);\n              if (!total) return "0";\n              return Number(total / opts.config?.series?.length).toFixed(2) + "%";\n            },\n          },\n          value: {\n            fontFamily: "inherit",\n            fontSize: "16px",\n            color: "var(--color-muted-foreground)",\n            formatter(val) {\n              return Number(val).toFixed(0) + "%";\n            },\n          },\n        },\n      },\n    },\n    legend: {\n      fontFamily: "inherit",\n      fontWeight: 500,\n      show: true,\n      position: "bottom",\n      labels: {\n        colors: "var(--color-muted-foreground)",\n      },\n    },\n    stroke: {\n      lineCap: "round",\n    },\n    colors: ["var(--color-violet-400)", "var(--color-violet-700)", "var(--color-violet-900)"],\n\n    chart: {\n      toolbar: {\n        show: window.innerWidth > 768,\n      },\n    },\n    labels: ["Apples", "Oranges", "Bananas"],\n  };\n</script>\n\n<style>\n  .apexcharts-menu {\n    border-color: var(--color-border);\n    background-color: var(--color-background);\n    color: var(--color-foreground);\n\n    .apexcharts-menu-item {\n      &:hover {\n        background-color: var(--color-primary) !important;\n        color: var(--color-primary-foreground) !important;\n      }\n    }\n  }\n</style>\n',
