    name: "Error Image",
    fileName: "BlockErrorImage.vue",
    file: '<template>\n  <!-- \n    Error page with split image layout\n    Features: Two-column split, decorative image, animated content\n  -->\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="{\n      initial: { opacity: 0 },\n      animate: {\n        opacity: 1,\n        transition: {\n          when: \'beforeChildren\',\n          delayChildren: stagger(0.15),\n        },\n      },\n    }"\n  >\n    <div class="relative flex min-h-screen items-center overflow-x-hidden">\n      <div class="container flex w-full items-center justify-center md:w-1/2">\n        <div>\n          <Motion\n            as="p"\n            :variants="childVariant"\n            class="text-primary mb-5 font-bold tracking-tight"\n          >\n            {{ statusCode }} error\n          </Motion>\n          <Motion\n            as="h1"\n            :variants="childVariant"\n            class="text-4xl font-bold tracking-tight lg:text-5xl"\n          >\n            {{ title }}\n          </Motion>\n          <Motion :variants="childVariant">\n            <UiButton class="mt-5" @click="clearError({ redirect: \'#\' })">\n              Take me home\n              <Icon name="lucide:arrow-right" class="ml-2 h-4 w-4" />\n            </UiButton>\n          </Motion>\n        </div>\n      </div>\n      <Motion\n        :variants="{\n          initial: { opacity: 0, x: 30 },\n          animate: {\n            opacity: 1,\n            x: 0,\n            transition: {\n              type: \'spring\',\n              stiffness: 200,\n              damping: 25,\n            },\n          },\n        }"\n        class="hidden h-screen md:block md:w-1/2 lg:w-1/2"\n      >\n        <img\n          src="https://images.unsplash.com/photo-1512551980832-13df02babc9e?q=60&w=2864&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D"\n          alt="Error page image"\n          class="size-full object-cover"\n        />\n      </Motion>\n    </div>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 20 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n\n  const props = withDefaults(\n    defineProps<{\n      statusCode?: number;\n      fatal?: boolean;\n      unhandled?: boolean;\n      statusMessage?: string;\n      message?: string;\n      data?: unknown;\n      cause?: unknown;\n    }>(),\n    {\n      statusCode: 404,\n      fatal: false,\n      unhandled: false,\n      statusMessage: "",\n      message: "We can\'t find this page",\n      data: undefined,\n      cause: undefined,\n    }\n  );\n\n  const title = computed(() => {\n    if (!props.message) return "Error";\n    return props.message;\n  });\n\n  useSeoMeta({ title });\n</script>\n',
