    name: "Blog Section 7",
    fileName: "BlockBlogSection7.vue",
    file: '<template>\n  <!-- \n    Timeline-style blog section with chronological layout\n    Features: Date markers, connecting line, slide-in animations\n  -->\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="{\n      initial: { opacity: 0 },\n      animate: {\n        opacity: 1,\n        transition: {\n          when: \'beforeChildren\',\n          delayChildren: stagger(0.15),\n        },\n      },\n    }"\n  >\n    <UiContainer class="py-16 lg:py-24">\n      <!-- Header -->\n      <div class="mb-12 lg:mb-16">\n        <Motion as="p" :variants="childVariant" class="text-primary mb-2 font-semibold">\n          Our journey\n        </Motion>\n        <Motion as="h3" :variants="childVariant" class="mb-3 text-3xl font-semibold lg:text-4xl">\n          Recent updates\n        </Motion>\n        <Motion as="p" :variants="childVariant" class="text-muted-foreground text-lg lg:text-xl">\n          Follow our latest stories and announcements\n        </Motion>\n      </div>\n\n      <!-- Timeline -->\n      <div class="relative space-y-12">\n        <!-- Vertical line (hidden on mobile) -->\n        <Motion\n          :initial="{ height: 0 }"\n          :animate="{\n            height: \'100%\',\n            transition: { duration: 1, delay: 0.2 },\n          }"\n          class="from-primary via-primary/50 absolute top-0 left-px hidden w-0.5 bg-linear-to-b to-transparent md:block"\n        ></Motion>\n\n        <!-- Timeline items -->\n        <Motion\n          v-for="(item, index) in 4"\n          :key="item"\n          :variants="{\n            initial: { opacity: 0 },\n            animate: {\n              opacity: 1,\n              transition: {\n                delay: index * 0.1,\n              },\n            },\n          }"\n          class="relative md:pl-12"\n        >\n          <!-- Timeline dot -->\n          <Motion\n            :variants="{\n              initial: { scale: 0, opacity: 0 },\n              animate: {\n                scale: [1, 1.3, 1],\n                opacity: 1,\n                transition: {\n                  delay: index * 0.1,\n                },\n              },\n            }"\n            class="bg-primary ring-background absolute top-3 left-0 hidden size-4 -translate-x-1.5 rounded-full ring-4 md:block"\n          ></Motion>\n\n          <!-- Content card -->\n          <UiCard class="group overflow-hidden shadow-xs transition-all hover:shadow-lg">\n            <div class="grid grid-cols-1 items-start gap-6 md:grid-cols-5">\n              <!-- Date section -->\n              <div\n                class="flex items-start gap-3 pl-5 md:col-span-1 md:h-full md:flex-col md:items-end md:justify-start md:border-r md:pr-6 md:pl-0"\n              >\n                <UiBadge variant="outline" class="shrink-0 py-1">\n                  <Icon name="lucide:calendar" class="mr-1.5 h-3 w-3" />\n                  {{ date }}\n                </UiBadge>\n                <span class="text-muted-foreground text-sm">5 min read</span>\n              </div>\n\n              <!-- Image section -->\n              <div class="relative overflow-hidden rounded-md md:col-span-2">\n                <img\n                  :src="image"\n                  :alt="alt"\n                  class="h-full w-full object-cover transition-transform duration-500 group-hover:scale-110"\n                />\n              </div>\n\n              <!-- Content section -->\n              <UiCardContent class="flex flex-col justify-center md:col-span-2">\n                <UiBadge class="mb-3 w-fit" variant="secondary">{{ headline }}</UiBadge>\n                <NuxtLink :to="link">\n                  <h4\n                    class="hover:text-primary mb-2 text-xl font-semibold transition-colors lg:text-2xl"\n                  >\n                    {{ title }}\n                  </h4>\n                </NuxtLink>\n                <p class="text-muted-foreground mb-4 line-clamp-2">{{ description }}</p>\n                <div class="flex items-center gap-3">\n                  <UiAvatar :src="userImage" :alt="userName" size="sm" />\n                  <div>\n                    <p class="text-sm font-medium">{{ userName }}</p>\n                    <p class="text-muted-foreground text-xs">Author</p>\n                  </div>\n                </div>\n              </UiCardContent>\n            </div>\n          </UiCard>\n        </Motion>\n      </div>\n\n      <!-- View all button -->\n      <Motion :variants="childVariant" class="mt-12 text-center">\n        <UiButton size="lg" variant="outline">\n          View complete timeline\n          <Icon name="lucide:arrow-right" class="ml-2 h-4 w-4" />\n        </UiButton>\n      </Motion>\n    </UiContainer>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, x: -30 },\n    animate: {\n      opacity: 1,\n      x: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 25,\n      },\n    },\n  };\n\n  const headline = "Update";\n  const title = "Introducing new collaboration features";\n  const image =\n    "https://images.unsplash.com/photo-1620121692029-d088224ddc74?q=80&w=1932&auto=format&fit=crop";\n  const alt = "Collaboration features";\n  const description =\n    "We\'re excited to announce new tools that make team collaboration easier and more productive.";\n  const date = "Apr 12, 2024";\n  const userImage = "https://i.pravatar.cc/300?img=30";\n  const userName = "David Lee";\n  const link = "#";\n</script>\n',
